const Redis = require('ioredis');
const redis = new Redis();
const BLOOM_KEY = 'bloom:product-ids';

async function initializeBloomFilter(expectedItems, errorRate) {
  await redis.call('BF.ADD', BLOOM_KEY, '__reserved__');
  const info = await redis.call('BF.INFO', BLOOM_KEY);
  console.log('Bloom filter created:', info);
}

async function addProductId(productId) {
  await redis.call('BF.ADD', BLOOM_KEY, productId);
}

async function isProductLikelyExist(productId) {
  const exists = await redis.call('BF.EXISTS', BLOOM_KEY, productId);
  return exists === 1;
}

// Example usage
(async () => {
  await initializeBloomFilter(100000, 0.01);
  await addProductId('product-123');
  console.log(await isProductLikelyExist('product-123'));
  console.log(await isProductLikelyExist('product-999999'));
})();

using StackExchange.Redis;

public class BloomFilterService
{
    private readonly IDatabase _db;
    private const string BloomKey = "bloom:product-ids";

    public BloomFilterService(IConnectionMultiplexer redis)
    {
        _db = redis.GetDatabase();
    }

    public async Task AddAsync(string item)
    {
        await _db.ScriptEvaluateAsync(
            "return redis.call('BF.ADD', KEYS[1], ARGV[1])",
            new RedisKey[] { BloomKey },
            new RedisValue[] { item });
    }

    public async Task<bool> ExistsAsync(string item)
    {
        var result = (long)await _db.ScriptEvaluateAsync(
            "return redis.call('BF.EXISTS', KEYS[1], ARGV[1])",
            new RedisKey[] { BloomKey },
            new RedisValue[] { item });
        return result == 1;
    }
}
